#!/usr/bin/python3
"""Merge transaction CSV exports safely into ../merged.csv."""

import csv
import os
import stat
import sys
import tempfile
from contextlib import nullcontext

BASE_DIR = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
OUTPUT = os.path.join(BASE_DIR, "merged.csv")


class MergeError(Exception):
    pass


def source_context(path):
    if path is None:
        return nullcontext(sys.stdin)
    return open(path, "r", encoding="utf-8-sig", newline="")


def main():
    paths = sys.argv[1:]
    sources = [(path, path) for path in paths] if paths else [(None, "<stdin>")]
    header = None
    id_index = None
    records = {}

    for path, label in sources:
        try:
            with source_context(path) as stream:
                reader = csv.reader(stream, strict=True)
                try:
                    source_header = next(reader)
                except StopIteration:
                    raise MergeError("{}: empty input".format(label))

                if header is None:
                    header = source_header
                    if header.count("transaction_id") != 1:
                        raise MergeError(
                            "{}: header must contain exactly one transaction_id column".format(label)
                        )
                    id_index = header.index("transaction_id")
                elif source_header != header:
                    raise MergeError(
                        "{}: header does not match the first input".format(label)
                    )

                for row in reader:
                    line_number = reader.line_num
                    if len(row) != len(header):
                        raise MergeError(
                            "{}:{}: expected {} fields, found {}".format(
                                label, line_number, len(header), len(row)
                            )
                        )

                    raw_id = row[id_index].strip()
                    try:
                        numeric_id = int(raw_id, 10)
                    except ValueError:
                        raise MergeError(
                            "{}:{}: transaction_id {!r} is not an integer".format(
                                label, line_number, row[id_index]
                            )
                        )
                    if not raw_id:
                        raise MergeError(
                            "{}:{}: transaction_id is empty".format(label, line_number)
                        )

                    data = tuple(row[:id_index] + row[id_index + 1 :])
                    previous = records.get(numeric_id)
                    if previous is None:
                        records[numeric_id] = (row, data, label, line_number)
                    elif previous[1] != data:
                        raise MergeError(
                            "conflicting duplicate transaction_id {}: {}:{} has {!r}; "
                            "{}:{} has {!r}".format(
                                numeric_id,
                                previous[2],
                                previous[3],
                                previous[0],
                                label,
                                line_number,
                                row,
                            )
                        )
        except (OSError, UnicodeError, csv.Error) as exc:
            raise MergeError("{}: {}".format(label, exc))

    temporary = None
    try:
        output_mode = (
            stat.S_IMODE(os.stat(OUTPUT).st_mode) if os.path.exists(OUTPUT) else 0o644
        )
        handle = tempfile.NamedTemporaryFile(
            mode="w",
            encoding="utf-8",
            newline="",
            dir=BASE_DIR,
            prefix=".merged.csv.",
            delete=False,
        )
        temporary = handle.name
        with handle:
            writer = csv.writer(handle, lineterminator="\n")
            writer.writerow(header)
            for numeric_id in sorted(records):
                writer.writerow(records[numeric_id][0])
            handle.flush()
            os.fsync(handle.fileno())
        os.chmod(temporary, output_mode)
        os.replace(temporary, OUTPUT)
        temporary = None
    finally:
        if temporary is not None:
            try:
                os.unlink(temporary)
            except FileNotFoundError:
                pass


if __name__ == "__main__":
    try:
        main()
    except MergeError as exc:
        print("merge: error: {}".format(exc), file=sys.stderr)
        sys.exit(1)
